void backtrack(State& s, vector<Solution>& out) {
    if (isGoal(s)) { out.push_back(extract(s)); return; }
    for (auto& choice : choices(s)) {
        apply(s, choice);        // try
        backtrack(s, out);       // recurse
        undo(s, choice);         // un-try
    }
}

bool safe(vector<int>& col, int r, int c) {
    for (int i = 0; i < r; i++)
        if (col[i] == c || abs(col[i]-c) == abs(i-r)) return false;
    return true;
}
void solve(int r, int n, vector<int>& col, int& count) {
    if (r == n) { count++; return; }
    for (int c = 0; c < n; c++)
        if (safe(col, r, c)) {
            col[r] = c;          // place
            solve(r+1, n, col, count);
            col[r] = -1;         // remove (backtrack)
        }
}

// choose -> explore -> un-choose. The un-choose is what makes it
// backtracking rather than plain recursion.
static void permute(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> out) {
    if (cur.size() == nums.length) { out.add(new ArrayList<>(cur)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true; cur.add(nums[i]);        // choose
        permute(nums, used, cur, out);           // explore
        cur.remove(cur.size() - 1); used[i] = false; // un-choose
    }
}

